import numpy as np
import time
from scipy.optimize import minimize


def _C_from_heights(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _make_h(b, c, N):
    # steps on [-1/4, 1/4]; use midpoints for x
    x = (np.arange(N) + 0.5) / N - 0.5  # in [-0.5, 0.5]
    x = x * 0.5  # scale to [-0.25, 0.25]
    h = np.where(x < 0, 1.0 + b * x, 1.0 + c * x)
    h = np.maximum(h, 0.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    best_h = None
    best_C = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_C = _C_from_heights(s)

    N_opt = 1000
    N_out = 30000

    def obj(params):
        b, c = params
        h = _make_h(b, c, N_opt)
        if h.sum() <= 0:
            return 1e6
        return _C_from_heights(h)

    # Nelder-Mead starting from a few points
    starts = [(2.0, 2.0), (0.0, 0.0), (1.0, 3.0), (3.0, 1.0)]
    for p0 in starts:
        if time.process_time() - t0 > budget_seconds * 0.7:
            break
        try:
            res = minimize(obj, np.array(p0), method='Nelder-Mead',
                           options={'xatol': 1e-6, 'fatol': 1e-10, 'maxiter': 2000})
            b, c = res.x
            h = _make_h(b, c, N_out)
            C = _C_from_heights(h)
            if C < best_C:
                best_C = C
                best_h = h
        except Exception:
            pass

    # Also try a few direct candidates with N_out
    for b, c in [(2.0, 2.0), (0.0, 0.0)]:
        if time.process_time() - t0 > budget_seconds * 0.9:
            break
        h = _make_h(b, c, N_out)
        C = _C_from_heights(h)
        if C < best_C:
            best_C = C
            best_h = h

    if best_h is None:
        best_h = np.ones(50)
    return np.asarray(best_h, dtype=float)

