    # step centers on [-1/4, 1/4]
    x = (np.arange(N) + 0.5) / N - 0.5  # in [-0.5, 0.5]; scale to [-1/4,1/4]
    x = x * 0.5  # now in [-1/4, 1/4]

    best_b = 2.0
    best_C = np.inf

    # Optimize slope b on a coarser grid for speed
    Nc = 1000
    xc = ((np.arange(Nc) + 0.5) / Nc - 0.5) * 0.5

    def obj(b):
        h = 1.0 + b * xc
        h = np.maximum(h, 0.0)
