import numpy as np
import time
from scipy.optimize import minimize_scalar


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    N = len(h)
    return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)


def _trapezoid(N, a):
    # x in [-1/4, 1/4], step centers
    x = (np.arange(N) + 0.5) / N - 0.5  # in [-0.5, 0.5)
    x = x * 0.5  # scale to [-1/4, 1/4]
    ax = np.abs(x)
    h = np.zeros(N)
    inner = ax <= a
    h[inner] = 1.0
    outer = (ax > a) & (ax < 0.25)
    h[outer] = (0.25 - ax[outer]) / (0.25 - a)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    N_opt = 1000

    def objective(a):
        if a < 0 or a >= 0.25:
            return np.inf
        h = _trapezoid(N_opt, a)
        return _C(h)

    res = minimize_scalar(objective, bounds=(0.0, 0.249), method='bounded',
                          options={'xatol': 1e-4})
    a_best = res.x
    h_best = _trapezoid(30000, a_best)

    # Sanity: if start is better, keep it (shouldn't happen per hypothesis)
    if start is not None:
        try:
            s = np.asarray(start, dtype=float)
            if s.ndim == 1 and s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
                if _C(s) < _C(h_best):
                    return s
        except Exception:
            pass

    return h_best

