        try:
            res = minimize(obj, np.array(s0), method='Nelder-Mead',
                           options={'xatol': 1e-6, 'fatol': 1e-10, 'maxiter': 2000})
            if best is None or res.fun < best.fun:
                best = res
        except Exception:
