def _make_h_interp(v, N):
    # knots at -0.25,-0.125,0,0.125,0.25 ; grid midpoints on [-0.25,0.25]
    knots = np.array([-0.25, -0.125, 0.0, 0.125, 0.25])
    x = (np.arange(N) + 0.5) / N - 0.5
    x = x * 0.5
    h = np.interp(x, knots, v)
    return np.maximum(h, 0.0)


def construct(budget_seconds, start):
