import numpy as np
import time
from scipy.optimize import minimize


def _C_from_heights(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _build(v, N):
    # v = [h0,h1,h2,h3, g1,g2,g3]; heights normalized so h0=1, gaps via exp
    h = np.maximum(np.asarray(v[:4], dtype=float), 0.0)
    if h[0] <= 0:
        h[0] = 1.0
    h = h / h[0]
    g = np.exp(np.clip(np.asarray(v[4:7], dtype=float), -20, 20))
    g = g / g.sum() * 0.5
    b = np.cumsum(g)  # boundaries in [0,0.5]
    x = (np.arange(N) + 0.5) / N * 0.5  # centers in [0,0.5]
    idx = np.searchsorted(b, x, side='right')
    idx = np.clip(idx, 0, 3)
    return h[idx]


def construct(budget_seconds, start):
    t0 = time.process_time()
    best_h = None
    best_C = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_C = _C_from_heights(s)

    N_opt = 1000
    N_out = 30000

    def obj(params):
        h = _build(params, N_opt)
        if h.sum() <= 0:
            return 1e6
        return _C_from_heights(h)

    inits = []
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size >= 4 and s.sum() > 0:
            n = s.size
            avgs = np.array([s[(np.arange(n) * 4) // n == k].mean() for k in range(4)])
            if avgs[0] > 0:
                avgs = avgs / avgs[0]
            inits.append(np.concatenate([avgs, np.zeros(3)]))
    inits.append(np.array([1.0, 2.0, 2.0, 1.0, 0.0, 0.0, 0.0]))
    inits.append(np.array([1.0, 1.0, 1.0, 1.0, 0.0, 0.0, 0.0]))

    for p0 in inits:
        if time.process_time() - t0 > budget_seconds * 0.75:
            break
        try:
            res = minimize(obj, p0, method='Nelder-Mead',
                           options={'xatol': 1e-9, 'fatol': 1e-13, 'maxiter': 20000})
            h = _build(res.x, N_out)
            C = _C_from_heights(h)
            if C < best_C:
                best_C = C
                best_h = h
        except Exception:
            pass

    if best_h is None:
        best_h = np.ones(50)
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize_scalar


def _C_from_heights(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _resample(h, N_out):
    # h lives on N_in midpoints of [-0.25,0.25]; resample to N_out midpoints
    h = np.asarray(h, dtype=float)
    N_in = h.size
    if N_in == N_out:
        return h.copy()
    x_in = (np.arange(N_in) + 0.5) / N_in - 0.5   # in [-0.5,0.5] units
    x_out = (np.arange(N_out) + 0.5) / N_out - 0.5
    # scale to [-0.25,0.25]
    return np.interp(x_out * 0.5, x_in * 0.5, h, left=0.0, right=0.0)


def _truncate(h, a):
    # zero out entries with |x| > a, x on midpoints of [-0.25,0.25]
    h = np.asarray(h, dtype=float)
    N = h.size
    x = ((np.arange(N) + 0.5) / N - 0.5) * 0.5
    out = h.copy()
    out[np.abs(x) > a] = 0.0
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()

    # Base profile: start if given, else a fallback
    if start is not None:
        base = np.asarray(start, dtype=float)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(1000)
    else:
        base = np.ones(1000)

    best_h = base.copy()
    best_C = _C_from_heights(base)

    # Work on N=1000 grid for the search
    N_search = 1000
    h_search = _resample(base, N_search)

    def obj_a(a):
        h = _truncate(h_search, a)
        if h.sum() <= 0:
            return 1e6
        return _C_from_heights(h)

    # Scan a range, then refine with minimize_scalar
    a_grid = np.linspace(0.05, 0.25, 41)
    best_a = 0.25
    best_Ca = np.inf
    for a in a_grid:
        if time.process_time() - t0 > budget_seconds * 0.4:
            break
        c = obj_a(a)
        if c < best_Ca:
            best_Ca = c
            best_a = a

    # Refine around best_a
