import time
from scipy.optimize import minimize


def _C_from_heights(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _make_h_interp(v, knots, N):
    x = (np.arange(N) + 0.5) / N - 0.5
    x = x * 0.5
    h = np.interp(x, knots, v)
    return np.maximum(h, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    best_h = None
    best_C = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_C = _C_from_heights(s)

    N_opt = 1000
    N_out = 30000
    # 9 equally spaced knots on [-0.25, 0.25]
    knots = np.linspace(-0.25, 0.25, 9)
    nk = len(knots)
    center = nk // 2  # index 4 -> x=0

    # initial guess: sample start (or default) at knots
    if best_h is not None and best_h.size > 0:
        xs = (np.arange(best_h.size) + 0.5) / best_h.size - 0.5
        xs = xs * 0.5
        v_init = np.interp(knots, xs, best_h)
    else:
        v_init = np.ones(nk)
    v_init = np.maximum(v_init, 1e-6)
    if v_init[center] > 0:
        v_init = v_init / v_init[center]
    v_init = np.clip(v_init, 1e-6, 10.0)

    # free indices: all except center
    free_idx = [i for i in range(nk) if i != center]

    def unpack(p):
        v = np.empty(nk)
        v[center] = 1.0
        for j, i in enumerate(free_idx):
            v[i] = p[j]
        return np.clip(v, 1e-6, 10.0)

    def obj(p):
        v = unpack(p)
        h = _make_h_interp(v, knots, N_opt)
        if h.sum() <= 0:
            return 1e6
        return _C_from_heights(h)

    p0 = np.array([v_init[i] for i in free_idx])

    starts = [p0,
              np.ones(len(free_idx)),
              np.array([v_init[i] * (1.0 + 0.15 * ((i % 3) - 1)) for i in free_idx])]
    starts = [np.clip(sp, 1e-6, 10.0) for sp in starts]

    for sp in starts:
        if time.process_time() - t0 > budget_seconds * 0.7:
            break
        try:
            res = minimize(obj, sp, method='Nelder-Mead',
                           options={'xatol': 1e-7, 'fatol': 1e-12, 'maxiter': 6000})
            v = unpack(res.x)
            h = _make_h_interp(v, knots, N_out)
            C = _C_from_heights(h)
            if C < best_C:
                best_C = C
                best_h = h
        except Exception:
            pass

    if best_h is None:
        best_h = np.ones(50)
    return np.asarray(best_h, dtype=float)

