def _resample(h, N):
    xs = (np.arange(len(h)) + 0.5) / len(h)
    xt = (np.arange(N) + 0.5) / N
    out = np.interp(xt, xs, h)
    return np.maximum(out, 0.0)


def _block_average(h, N):
    h = np.asarray(h, dtype=float)
    M = len(h)
    if M == N:
        return h.copy()
    if M % N == 0:
        return h.reshape(N, M // N).mean(axis=1)
    # general: integrate via cumulative sum
    cs = np.concatenate([[0.0], np.cumsum(h)])
    edges = np.linspace(0, M, N + 1)
    out = np.empty(N)
    for i in range(N):
        a = edges[i]
        b = edges[i + 1]
        ia = int(np.floor(a))
        ib = int(np.floor(b))
        if ib <= ia:
            out[i] = h[min(ia, M - 1)]
        else:
            s = 0.0
            if ia < M:
                s += (min(ia + 1, b) - a) * h[ia]
            if ia + 1 < ib:
                s += cs[ib] - cs[ia + 1]
            if ib < M:
                s += (b - ib) * h[ib]
            out[i] = s / (b - a)
    return np.maximum(out, 0.0)


