def construct(budget_seconds, start):
    t0 = time.process_time()
    rng = random.Random(12345)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_C = _C_from_heights(s)
        else:
            best_h = np.ones(3000)
            best_C = _C_from_heights(best_h)
    else:
        best_h = np.ones(3000)
        best_C = _C_from_heights(best_h)

    # Coarse hopping at N=1000.
    coarse = _block_average(best_h, 1000)
    coarse_C = _C_from_heights(coarse)
    if coarse_C < best_C:
        pass  # don't replace best_h with coarse; just use as seed

    hop_best_h = coarse.copy()
    hop_best_C = coarse_C

    eps_list = [0.02, 0.05]
    m_list = [1, 2, 3, 4, 5]
    trials = []
    for eps in eps_list:
        for m in m_list:
            trials.append((eps, m))
    # 12 trials: cycle through
    n_trials = 12
    for ti in range(n_trials):
        if time.process_time() - t0 > budget_seconds * 0.35:
            break
        eps, m = trials[ti % len(trials)]
        h_seed = _perturb(coarse, eps, m, rng)
        try:
            ha, Ca = _lbfgs_h_active(h_seed, t0, budget_seconds,
                                     rel_tol=1e-6, m=30, maxiter=150,
                                     maxfun=300, time_frac=0.35)
            if Ca < hop_best_C:
                hop_best_C = Ca
                hop_best_h = ha.copy()
            if time.process_time() - t0 < budget_seconds * 0.33:
                he, Ce = _lbfgs_h_exact(ha, t0, budget_seconds, m=30,
                                        maxiter=100, maxfun=200,
                                        time_frac=0.35)
                if Ce < hop_best_C:
                    hop_best_C = Ce
                    hop_best_h = he.copy()
        except Exception:
            pass

    # Upsample hop best to N=3000 and N=30000, keep best.
    candidates = [best_h]
    for N in (3000, 30000):
        up = _resample(hop_best_h, N)
        candidates.append(up)
    for c in candidates:
        cc = _C_from_heights(c)
        if cc < best_C:
            best_C = cc
            best_h = c.copy()

    # Tight continuation rel_tol [1e-9, 1e-10, 1e-11].
    for rt in [1e-9, 1e-10, 1e-11]:
        if time.process_time() - t0 > budget_seconds * 0.85:
            break
        try:
            ha, Ca = _lbfgs_h_active(best_h, t0, budget_seconds,
                                     rel_tol=rt, m=30, maxiter=200,
                                     maxfun=400, time_frac=0.85)
            if Ca < best_C:
                best_C = Ca
                best_h = ha.copy()
        except Exception:
            pass

    # Exact-max polish.
    if time.process_time() - t0 < budget_seconds * 0.92:
        try:
            he, Ce = _lbfgs_h_exact(best_h, t0, budget_seconds, m=30,
                                    maxiter=300, maxfun=600,
                                    time_frac=0.92)
            if Ce < best_C:
                best_C = Ce
                best_h = he.copy()
        except Exception:
            pass

    # z-space polish.
    if time.process_time() - t0 < budget_seconds * 0.97:
        try:
            hf, Cf = _lbfgs_polish(best_h, t0, budget_seconds, maxiter=300,
                                   maxfun=600, m=30, time_frac=0.97)
            if Cf < best_C:
                best_C = Cf
                best_h = hf.copy()
        except Exception:
            pass

    return np.asarray(best_h, dtype=float)

