def _project_simplex(v):
    u = np.sort(v)[::-1]
    css = np.cumsum(u)
    rho = np.nonzero(u * np.arange(1, len(v) + 1) > (css - 1.0))[0][-1]
    theta = (css[rho] - 1.0) / (rho + 1.0)
    return np.maximum(v - theta, 0.0)


def _qp_fixed_lags(h0, K, t0, budget, time_frac, n_iter=300, lr0=1e-3):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    N = len(h)
    S0 = h.sum()
    if S0 <= 0:
        return h0, _C_from_heights(h0)
    h = h / S0
    nfft = 65536
    while nfft < 2 * N:
        nfft <<= 1

    def conv_of(hh):
        return np.fft.irfft(np.fft.rfft(hh, nfft) ** 2, nfft)[:2 * N - 1]

    conv = conv_of(h)
    kk = min(K, conv.size)
    idx_top = np.argpartition(conv, -kk)[-kk:]

    def Q_and_g(hh):
        c = conv_of(hh)
        Q = c[idx_top].mean()
        g = np.zeros(N)
        w = 2.0 / kk
        for kpos in idx_top:
            lo = max(0, kpos - (N - 1))
            hi = min(N - 1, kpos)
            idx = np.arange(lo, hi + 1)
            g[idx] += w * hh[kpos - idx]
        return Q, g

    Q, g = Q_and_g(h)
    lr = lr0
    for it in range(n_iter):
        if time.process_time() - t0 > budget * time_frac:
            break
        h_new = _project_simplex(h - lr * g)
        Q_new, g_new = Q_and_g(h_new)
        if Q_new < Q:
            h, Q, g = h_new, Q_new, g_new
            lr *= 1.05
        else:
            lr *= 0.5
            if lr < 1e-12:
                break

    h_out = h * S0
    return h_out, _C_from_heights(h_out)


