def _lbfgs_topk(h0, t0, budget, k=200, m=30, maxiter=300, maxfun=600,
                time_frac=0.90):
    h0 = np.maximum(np.asarray(h0, dtype=float), 1e-12)
    N = len(h0)
    nfft = 65536
    while nfft < 2 * N:
        nfft <<= 1
    state = {'best_h': h0.copy(), 'best_C': _C_from_heights(h0),
             'stop': False}

    def fun(h):
        if time.process_time() - t0 > budget * time_frac:
            state['stop'] = True
        h = np.maximum(h, 1e-12)
        S, conv = _conv_and_grad(h, N, nfft)
        kk = min(k, conv.size)
        idx_top = np.argpartition(conv, -kk)[-kk:]
        vals = conv[idx_top]
        mean_top = vals.mean()
        Ck = 2.0 * N * mean_top / (S * S)
        g = np.zeros(N)
        w = 1.0 / kk
        for kpos in idx_top:
            lo = max(0, kpos - (N - 1))
            hi = min(N - 1, kpos)
            idx = np.arange(lo, hi + 1)
            g[idx] += w * 4.0 * N * h[kpos - idx] / (S * S)
        g -= 2.0 * Ck / S
        Cexact = 2.0 * N * conv.max() / (S * S)
        if Cexact < state['best_C']:
            state['best_C'] = Cexact
            state['best_h'] = h.copy()
        return Ck, g

    try:
        minimize(fun, h0, jac=True, method='L-BFGS-B',
                 bounds=[(0.0, 1e6)] * N,
                 options={'maxiter': maxiter, 'maxfun': maxfun,
                          'ftol': 1e-18, 'gtol': 1e-12, 'm': m},
                 callback=lambda hk: (_ for _ in ()).throw(StopIteration)
                 if state['stop'] else None)
    except StopIteration:
        pass
    except Exception:
        pass

    return state['best_h'], state['best_C']


def _block_average(h, Nc):
    N = len(h)
    if N == Nc:
        return h.copy()
    edges = np.linspace(0, N, Nc + 1).astype(int)
    out = np.empty(Nc)
    for i in range(Nc):
        a, b = edges[i], edges[i + 1]
        if b <= a:
            b = a + 1
        out[i] = h[a:b].mean()
    return out


def _linear_upsample(h, N):
    Nc = len(h)
    if Nc == N:
        return h.copy()
    xc = (np.arange(Nc) + 0.5) / Nc
    x = (np.arange(N) + 0.5) / N
    return np.interp(x, xc, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    time_frac = 0.90
    rng = np.random.default_rng(12345)

    best_h = None
    best_C = np.inf
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_C = _C_from_heights(s)

    if best_h is None:
        best_h = np.ones(3000)
        best_C = _C_from_heights(best_h)

    N_full = len(best_h)
    Nc = 3000
    hc0 = _block_average(best_h, Nc)
    if hc0.sum() <= 0:
        hc0 = np.ones(Nc)

    # Coarse-N top-k hopping trials
    eps_list = [0.02, 0.05]
    m_list = [1, 2, 3, 4]
    trials = []
    for eps in eps_list:
        for m in m_list:
            trials.append((eps, m))
    # 8 trials
    trials = trials[:8]

    xc = (np.arange(Nc) + 0.5) / Nc
    best_coarse_h = hc0.copy()
    best_coarse_C = _C_from_heights(hc0)

    for (eps, m) in trials:
        if time.process_time() - t0 > budget_seconds * time_frac:
            break
        phi = rng.uniform(0, 2 * np.pi)
        pert = hc0 * np.exp(eps * np.sin(2 * np.pi * m * xc + phi))
        pert = np.maximum(pert, 1e-12)
        h = pert
        try:
            for k in [100, 20, 5]:
                if time.process_time() - t0 > budget_seconds * time_frac:
                    break
                h, C = _lbfgs_topk(h, t0, budget_seconds, k=k, m=30,
                                   maxiter=300, maxfun=600,
                                   time_frac=time_frac)
            if time.process_time() - t0 > budget_seconds * time_frac:
                pass
            else:
                h, C = _lbfgs_h_exact(h, t0, budget_seconds, maxiter=300,
                                      maxfun=600, m=30, time_frac=time_frac)
            C = _C_from_heights(h)
            if C < best_coarse_C:
                best_coarse_C = C
                best_coarse_h = h.copy()
        except Exception:
            pass

    # Upsample best coarse to full N and polish
    if time.process_time() - t0 < budget_seconds * time_frac:
        h_full = _linear_upsample(best_coarse_h, N_full)
        h_full = np.maximum(h_full, 1e-12)
        C_full = _C_from_heights(h_full)
        if C_full < best_C:
            best_C = C_full
            best_h = h_full.copy()

        for k in [50, 10, 3]:
            if time.process_time() - t0 > budget_seconds * time_frac:
                break
            try:
                h, C = _lbfgs_topk(best_h, t0, budget_seconds, k=k, m=30,
                                   maxiter=300, maxfun=600,
                                   time_frac=time_frac)
                C = _C_from_heights(h)
                if C < best_C:
                    best_C = C
                    best_h = h.copy()
            except Exception:
                pass

        if time.process_time() - t0 < budget_seconds * time_frac:
            try:
                h, C = _lbfgs_h_active(best_h, t0, budget_seconds,
                                       rel_tol=1e-9, m=30, maxiter=300,
                                       maxfun=600, time_frac=time_frac)
                C = _C_from_heights(h)
                if C < best_C:
                    best_C = C
                    best_h = h.copy()
            except Exception:
                pass

        if time.process_time() - t0 < budget_seconds * time_frac:
            try:
                h, C = _lbfgs_h_exact(best_h, t0, budget_seconds, maxiter=300,
                                      maxfun=600, m=30, time_frac=time_frac)
                C = _C_from_heights(h)
                if C < best_C:
                    best_C = C
                    best_h = h.copy()
            except Exception:
                pass

    return np.asarray(best_h, dtype=float)

