    if N == M:
        return h.copy()
    edges = np.linspace(0, N, M + 1)
    out = np.empty(M)
    for i in range(M):
        a = int(round(edges[i]))
        b = int(round(edges[i + 1]))
        if b <= a:
            b = min(N, a + 1)
        out[i] = h[a:b].mean()
    return out


