        for kk, wk in zip(active, w):
            lo = max(0, kk - (N - 1))
            hi = min(N - 1, kk)
            idx = np.arange(lo, hi + 1)
            g[idx] += wk * 4.0 * N * h[kk - idx] / (S * S)
        g -= 2.0 * C / S
        if C < state['best_C']:
            state['best_C'] = C
            state['best_h'] = h.copy()
        return C, g

    try:
        minimize(fun, h0, jac=True, method='L-BFGS-B',
                 bounds=[(0.0, 1e6)] * N,
                 options={'maxiter': maxiter, 'maxfun': maxfun,
                          'ftol': 1e-18, 'gtol': 1e-12, 'm': m},
                 callback=lambda hk: (_ for _ in ()).throw(StopIteration)
                 if state['stop'] else None)
    except StopIteration:
        pass
    except Exception:
        pass

    return state['best_h'], state['best_C']


def _choose_tau(vals, cmax, target_M):
    # vals are top-k conv values; find tau in [1e-9,1e-3]*cmax s.t. ESS ~ target_M
    if vals.size == 0 or cmax <= 0:
        return 1e-6 * max(cmax, 1e-30)
    lo = 1e-9 * cmax
    hi = 1e-3 * cmax
    if hi <= 0:
        hi = 1e-30

    def ess(tau):
        z = (vals - cmax) / tau
        z -= z.max()
        w = np.exp(z)
        sw = w.sum()
        if sw <= 0:
            return 1.0
        return (sw * sw) / float(np.dot(w, w))

    # ESS increases with tau; bisect for target_M
    for _ in range(40):
        mid = 0.5 * (lo + hi)
        if ess(mid) < target_M:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def _lbfgs_topk_weighted(h0, t0, budget, k=200, target_M=80, m=30,
                         maxiter=300, maxfun=600, time_frac=0.90):
    h0 = np.maximum(np.asarray(h0, dtype=float), 1e-12)
    N = len(h0)
    nfft = 65536
    while nfft < 2 * N:
        nfft <<= 1
    state = {'best_h': h0.copy(), 'best_C': _C_from_heights(h0),
             'stop': False}

    def fun(h):
        if time.process_time() - t0 > budget * time_frac:
            state['stop'] = True
        h = np.maximum(h, 1e-12)
        S, conv = _conv_and_grad(h, N, nfft)
        kk = min(k, conv.size)
        idx_top = np.argpartition(conv, -kk)[-kk:]
        vals = conv[idx_top]
        cmax = float(vals.max())
        tau = _choose_tau(vals, cmax, target_M)
        if tau <= 0:
            tau = 1e-30
        z = (vals - cmax) / tau
        z = z - z.max()
        w = np.exp(z)
        w = w / w.sum()
        Ck = 2.0 * N * float(np.dot(w, vals)) / (S * S)
        g = np.zeros(N)
        for kpos, wk in zip(idx_top, w):
            lo = max(0, kpos - (N - 1))
            hi = min(N - 1, kpos)
            idx = np.arange(lo, hi + 1)
            g[idx] += wk * 4.0 * N * h[kpos - idx] / (S * S)
        g -= 2.0 * Ck / S
        Cexact = 2.0 * N * conv.max() / (S * S)
        if Cexact < state['best_C']:
            state['best_C'] = Cexact
            state['best_h'] = h.copy()
        return Ck, g

    try:
        minimize(fun, h0, jac=True, method='L-BFGS-B',
                 bounds=[(0.0, 1e6)] * N,
                 options={'maxiter': maxiter, 'maxfun': maxfun,
                          'ftol': 1e-18, 'gtol': 1e-12, 'm': m},
                 callback=lambda hk: (_ for _ in ()).throw(StopIteration)
                 if state['stop'] else None)
    except StopIteration:
        pass
    except Exception:
        pass

    return state['best_h'], state['best_C']


def _qp_k_active(h0, t0, budget, K=30, time_frac=0.92):
    # Solve small QP over K active lags: minimize max over active of conv_k
    # subject to sum h = 1, h >= 0. Use scipy minimize on h with K active lags.
    h0 = np.maximum(np.asarray(h0, dtype=float), 1e-12)
    N = len(h0)
    nfft = 65536
    while nfft < 2 * N:
        nfft <<= 1
    S0, conv0 = _conv_and_grad(h0, N, nfft)
    K = min(K, conv0.size)
    idx_top = np.argpartition(conv0, -K)[-K:]
    idx_top = np.sort(idx_top)
    state = {'best_h': h0.copy(), 'best_C': _C_from_heights(h0),
             'stop': False}

    def fun(h):
        if time.process_time() - t0 > budget * time_frac:
            state['stop'] = True
        h = np.maximum(h, 1e-12)
        S, conv = _conv_and_grad(h, N, nfft)
        vals = conv[idx_top]
        cmax = float(vals.max())
        C = 2.0 * N * cmax / (S * S)
        # gradient of max over active lags
        kpos = idx_top[int(np.argmax(vals))]
        g = np.zeros(N)
        lo = max(0, kpos - (N - 1))
        hi = min(N - 1, kpos)
        idx = np.arange(lo, hi + 1)
        g[idx] = 4.0 * N * h[kpos - idx] / (S * S)
        g -= 2.0 * C / S
        Cexact = 2.0 * N * conv.max() / (S * S)
        if Cexact < state['best_C']:
            state['best_C'] = Cexact
            state['best_h'] = h.copy()
        return C, g

    try:
        minimize(fun, h0, jac=True, method='L-BFGS-B',
                 bounds=[(0.0, 1e6)] * N,
                 options={'maxiter': 200, 'maxfun': 400,
                          'ftol': 1e-18, 'gtol': 1e-12, 'm': 20},
                 callback=lambda hk: (_ for _ in ()).throw(StopIteration)
                 if state['stop'] else None)
    except StopIteration:
        pass
    except Exception:
        pass

    return state['best_h'], state['best_C']


def construct(budget_seconds, start):
    t0 = time.process_time()
    best_h = None
    best_C = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_C = _C_from_heights(s)

    if best_h is None:
        best_h = np.ones(3000)
        best_C = _C_from_heights(best_h)

    time_frac = 0.90

    schedule = [(200, 80), (50, 30), (10, 10), (3, 3)]

    for cycle in range(2):
        if time.process_time() - t0 > budget_seconds * time_frac:
            break
        for k, M in schedule:
            if time.process_time() - t0 > budget_seconds * time_frac:
                break
            try:
                h_new, C_new = _lbfgs_topk_weighted(
                    best_h, t0, budget_seconds, k=k, target_M=M, m=30,
                    maxiter=250, maxfun=500, time_frac=time_frac)
                if C_new < best_C:
                    best_C, best_h = C_new, h_new.copy()
            except Exception:
                pass
            if time.process_time() - t0 > budget_seconds * time_frac:
                break
            try:
                ha, Ca = _lbfgs_h_active(best_h, t0, budget_seconds,
                                         rel_tol=1e-9, m=30,
                                         maxiter=300, maxfun=600,
                                         time_frac=time_frac)
                if Ca < best_C:
                    best_C, best_h = Ca, ha
            except Exception:
                pass
            if time.process_time() - t0 > budget_seconds * time_frac:
                break
            try:
                hf, Cf = _lbfgs_h_exact(best_h, t0, budget_seconds,
                                        maxiter=300, maxfun=600, m=30,
                                        time_frac=time_frac)
                if Cf < best_C:
                    best_C, best_h = Cf, hf
            except Exception:
                pass

    # QP K=30 then exact polish
    if time.process_time() - t0 < budget_seconds * 0.85:
        try:
            hq, Cq = _qp_k_active(best_h, t0, budget_seconds, K=30,
                                  time_frac=0.95)
            if Cq < best_C:
                best_C, best_h = Cq, hq
        except Exception:
            pass
    if time.process_time() - t0 < budget_seconds * 0.90:
        try:
            hf, Cf = _lbfgs_h_exact(best_h, t0, budget_seconds,
                                    maxiter=200, maxfun=400, m=30,
                                    time_frac=0.97)
            if Cf < best_C:
                best_C, best_h = Cf, hf
        except Exception:
            pass

    return np.asarray(best_h, dtype=float)

import numpy as np
import time
