        pass

    return state['best_h'], state['best_C']


def _lbfgs_topk_weighted(h0, t0, budget, k=200, m=30, maxiter=300,
                         maxfun=600, time_frac=0.90, tau_rel=1e-6):
    h0 = np.maximum(np.asarray(h0, dtype=float), 1e-12)
    N = len(h0)
    nfft = 65536
    while nfft < 2 * N:
        nfft <<= 1
    state = {'best_h': h0.copy(), 'best_C': _C_from_heights(h0),
             'stop': False}

    def fun(h):
        if time.process_time() - t0 > budget * time_frac:
            state['stop'] = True
        h = np.maximum(h, 1e-12)
        S, conv = _conv_and_grad(h, N, nfft)
        kk = min(k, conv.size)
        idx_top = np.argpartition(conv, -kk)[-kk:]
        vals = conv[idx_top]
        cmax = vals.max()
        tau = tau_rel * cmax
        if tau <= 0:
            tau = 1e-30
        z = (vals - cmax) / tau
        z = z - z.max()
        w = np.exp(z)
        w = w / w.sum()
        Ck = 2.0 * N * float(np.dot(w, vals)) / (S * S)
        g = np.zeros(N)
        for kpos, wk in zip(idx_top, w):
            lo = max(0, kpos - (N - 1))
            hi = min(N - 1, kpos)
            idx = np.arange(lo, hi + 1)
            g[idx] += wk * 4.0 * N * h[kpos - idx] / (S * S)
        g -= 2.0 * Ck / S
        Cexact = 2.0 * N * conv.max() / (S * S)
        if Cexact < state['best_C']:
            state['best_C'] = Cexact
            state['best_h'] = h.copy()
        return Ck, g

    try:
        minimize(fun, h0, jac=True, method='L-BFGS-B',
                 bounds=[(0.0, 1e6)] * N,
                 options={'maxiter': maxiter, 'maxfun': maxfun,
                          'ftol': 1e-18, 'gtol': 1e-12, 'm': m},
                 callback=lambda hk: (_ for _ in ()).throw(StopIteration)
                 if state['stop'] else None)
    except StopIteration:
        pass
    except Exception:
        pass

    return state['best_h'], state['best_C']


def _block_average(h, M):
    h = np.asarray(h, dtype=float)
    N = len(h)
    if N == M:
        return h.copy()
    edges = np.linspace(0, N, M + 1)
    out = np.empty(M)
    for i in range(M):
        a = int(round(edges[i]))
        b = int(round(edges[i + 1]))
        if b <= a:
            b = min(N, a + 1)
        out[i] = h[a:b].mean()
    return out


def _upsample(h, N):
    M = len(h)
    if M == N:
        return h.copy()
    xp = (np.arange(M) + 0.5) / M
    x = (np.arange(N) + 0.5) / N
    return np.interp(x, xp, h)


def _qp_polish(h0, t0, budget, K=50, steps=500, time_frac=0.95):
    """Projected-gradient QP polish on the top-K active knots."""
    h = np.maximum(np.asarray(h0, dtype=float), 1e-12)
    N = len(h)
    nfft = 65536
    while nfft < 2 * N:
        nfft <<= 1
    S, conv = _conv_and_grad(h, N, nfft)
    C = 2.0 * N * conv.max() / (S * S)
    best_h = h.copy()
    best_C = C
    kk = min(K, conv.size)
    idx_top = np.argpartition(conv, -kk)[-kk:]
    vals = conv[idx_top]
    cmax = vals.max()
    tau = 1e-6 * cmax if cmax > 0 else 1e-30
    z = (vals - cmax) / tau
    z -= z.max()
    w = np.exp(z)
    w /= w.sum()
    # Precompute gradient contributions for active knots.
    step = 1e-3
    for it in range(steps):
        if time.process_time() - t0 > budget * time_frac:
            break
        S = h.sum()
        if S <= 0:
            break
        g = np.zeros(N)
        for kpos, wk in zip(idx_top, w):
            lo = max(0, kpos - (N - 1))
            hi = min(N - 1, kpos)
            idx = np.arange(lo, hi + 1)
            g[idx] += wk * 4.0 * N * h[kpos - idx] / (S * S)
        g -= 2.0 * C / S
        # Normalize gradient scale.
        gn = np.linalg.norm(g)
        if gn <= 0:
            break
        h_new = np.maximum(h - step * g / gn * np.linalg.norm(h) / np.sqrt(N), 0.0)
        if h_new.sum() <= 0:
            break
        S2, conv2 = _conv_and_grad(h_new, N, nfft)
        C2 = 2.0 * N * conv2.max() / (S2 * S2)
        if C2 < C:
            h = h_new
            C = C2
            if C < best_C:
                best_C = C
                best_h = h.copy()
            step *= 1.1
        else:
            step *= 0.5
            if step < 1e-12:
                break
    return best_h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    best_h = None
    best_C = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_C = _C_from_heights(s)

    if best_h is None:
        best_h = np.ones(3000)
        best_C = _C_from_heights(best_h)

    time_frac = 0.90

    # Coarse phase: block-average to N=3000, weighted top-k hops.
    if time.process_time() - t0 < budget_seconds * time_frac:
        try:
            hc = _block_average(best_h, 3000)
            Cc = _C_from_heights(hc)
            for k in [100, 20, 5]:
                if time.process_time() - t0 > budget_seconds * time_frac * 0.45:
                    break
                try:
                    h_new, C_new = _lbfgs_topk_weighted(
                        hc, t0, budget_seconds, k=k, m=30,
                        maxiter=300, maxfun=600, time_frac=time_frac * 0.45,
                        tau_rel=1e-6)
                    if C_new < Cc:
                        Cc, hc = C_new, h_new.copy()
                except Exception:
                    pass
            # Upsample coarse result back to full N and compare.
            hu = _upsample(hc, len(best_h))
            Cu = _C_from_heights(hu)
            if Cu < best_C:
                best_C, best_h = Cu, hu
        except Exception:
            pass

    # Full-N weighted chain (p0119 style).
    for cycle in range(2):
        if time.process_time() - t0 > budget_seconds * time_frac:
            break
        for k in [200, 50, 10, 3]:
            if time.process_time() - t0 > budget_seconds * time_frac:
                break
            try:
                h_new, C_new = _lbfgs_topk_weighted(
                    best_h, t0, budget_seconds, k=k, m=30,
                    maxiter=250, maxfun=500, time_frac=time_frac,
                    tau_rel=1e-6)
                if C_new < best_C:
                    best_C, best_h = C_new, h_new.copy()
            except Exception:
                pass
            if time.process_time() - t0 > budget_seconds * time_frac:
                break
            try:
                ha, Ca = _lbfgs_h_active(best_h, t0, budget_seconds,
                                         rel_tol=1e-9, m=30,
                                         maxiter=300, maxfun=600,
                                         time_frac=time_frac)
                if Ca < best_C:
                    best_C, best_h = Ca, ha
            except Exception:
                pass
            if time.process_time() - t0 > budget_seconds * time_frac:
                break
            try:
                hf, Cf = _lbfgs_h_exact(best_h, t0, budget_seconds,
                                        maxiter=300, maxfun=600, m=30,
                                        time_frac=time_frac)
                if Cf < best_C:
                    best_C, best_h = Cf, hf
            except Exception:
                pass

    # QP polish on top-K active knots.
    if time.process_time() - t0 < budget_seconds * time_frac:
        try:
            hq, Cq = _qp_polish(best_h, t0, budget_seconds, K=50, steps=500,
                                time_frac=time_frac)
            if Cq < best_C:
                best_C, best_h = Cq, hq
        except Exception:
            pass

    # Final exact L-BFGS.
    if time.process_time() - t0 < budget_seconds * time_frac:
        try:
            hf, Cf = _lbfgs_h_exact(best_h, t0, budget_seconds,
                                    maxiter=300, maxfun=600, m=30,
                                    time_frac=time_frac)
            if Cf < best_C:
                best_C, best_h = Cf, hf
        except Exception:
            pass

    # Coarse N=5000 attempt if time permits.
    if time.process_time() - t0 < budget_seconds * time_frac * 0.85:
        try:
            hc5 = _block_average(best_h, 5000)
            Cc5 = _C_from_heights(hc5)
            for k in [100, 20]:
                if time.process_time() - t0 > budget_seconds * time_frac * 0.9:
                    break
                try:
                    h_new, C_new = _lbfgs_topk_weighted(
                        hc5, t0, budget_seconds, k=k, m=30,
                        maxiter=200, maxfun=400,
                        time_frac=time_frac * 0.9, tau_rel=1e-6)
                    if C_new < Cc5:
                        Cc5, hc5 = C_new, h_new.copy()
                except Exception:
                    pass
            hu5 = _upsample(hc5, len(best_h))
            Cu5 = _C_from_heights(hu5)
            if Cu5 < best_C:
                best_C, best_h = Cu5, hu5
        except Exception:
            pass

    return np.asarray(best_h, dtype=float)

