def _qp_polish(h0, t0, budget, K=30, steps=400, time_frac=0.90, power_iters=20):
    """Fixed-lag QP over K largest lags, projected gradient on simplex."""
    h = np.maximum(np.asarray(h0, dtype=float), 0.0).copy()
    N = len(h)
    s = h.sum()
    if s <= 0:
        return h0, _C_from_heights(h0)
    h = h / s
    nfft = 65536
    while nfft < 2 * N:
        nfft <<= 1
    _, conv = _conv_and_grad(h, N, nfft)
    K = min(K, conv.size)
    idx_top = np.argpartition(conv, -K)[-K:]

    def apply_A(x):
        _, c = _conv_and_grad(x, N, nfft)
        return c[idx_top]

    x_ref = h.copy()

    def apply_AT(y):
        g = np.zeros(N)
        for j, kk in enumerate(idx_top):
            if y[j] == 0.0:
                continue
            lo = max(0, kk - (N - 1))
            hi = min(N - 1, kk)
            idx = np.arange(lo, hi + 1)
            g[idx] += y[j] * x_ref[kk - idx]
        return g

    v = np.random.RandomState(0).randn(N)
    v = v / (np.linalg.norm(v) + 1e-30)
    L = 1.0
    for _ in range(power_iters):
        if time.process_time() - t0 > budget * time_frac:
            break
        Av = apply_A(v)
        w = apply_AT(Av)
        nw = np.linalg.norm(w)
        if nw < 1e-30:
            break
        v = w / nw
        L = nw
    L = max(L, 1e-12)
    step = 1.0 / (2.0 * L)

    best_h = h.copy()
    best_C = _C_from_heights(h)

    for it in range(steps):
        if time.process_time() - t0 > budget * time_frac:
            break
        x_ref = h
        _, conv = _conv_and_grad(h, N, nfft)
        g = np.zeros(N)
        for kk in idx_top:
            lo = max(0, kk - (N - 1))
            hi = min(N - 1, kk)
            idx = np.arange(lo, hi + 1)
            g[idx] += h[kk - idx]
        g /= float(K)
        h = h - step * g
        h = np.maximum(h, 0.0)
        ss = h.sum()
        if ss <= 0:
            h = np.ones(N) / N
        else:
            h = h / ss
        if (it & 15) == 15:
            C = _C_from_heights(h)
            if C < best_C:
                best_C = C
                best_h = h.copy()

    C = _C_from_heights(h)
    if C < best_C:
        best_C = C
        best_h = h.copy()
    return best_h, best_C


