             'stop': False}

    def fun(h):
        if time.process_time() - t0 > budget * time_frac:
            state['stop'] = True
        h = np.maximum(h, 1e-12)
        S, conv = _conv_and_grad(h, N, nfft)
        kk = min(k, conv.size)
        idx_top = np.argpartition(conv, -kk)[-kk:]
        vals = conv[idx_top]
        cmax = vals.max()
        tau = 1e-6 * cmax
        if tau <= 0:
            tau = 1e-30
        z = (vals - cmax) / tau
        z = z - z.max()
        w = np.exp(z)
        w = w / w.sum()
        Ck = 2.0 * N * float(np.dot(w, vals)) / (S * S)
        g = np.zeros(N)
        for kpos, wk in zip(idx_top, w):
            lo = max(0, kpos - (N - 1))
            hi = min(N - 1, kpos)
            idx = np.arange(lo, hi + 1)
            g[idx] += wk * 4.0 * N * h[kpos - idx] / (S * S)
        g -= 2.0 * Ck / S
        Cexact = 2.0 * N * conv.max() / (S * S)
        if Cexact < state['best_C']:
            state['best_C'] = Cexact
            state['best_h'] = h.copy()
        return Ck, g

    try:
        minimize(fun, h0, jac=True, method='L-BFGS-B',
                 bounds=[(0.0, 1e6)] * N,
                 options={'maxiter': maxiter, 'maxfun': maxfun,
                          'ftol': 1e-18, 'gtol': 1e-12, 'm': m},
                 callback=lambda hk: (_ for _ in ()).throw(StopIteration)
                 if state['stop'] else None)
    except StopIteration:
        pass
    except Exception:
        pass

    return state['best_h'], state['best_C']


def _qp_polish(h0, t0, budget, K=30, steps=400, time_frac=0.90, power_iters=20):
    """Fixed-lag QP over K largest lags, projected gradient on simplex."""
    h = np.maximum(np.asarray(h0, dtype=float), 0.0).copy()
    N = len(h)
    s = h.sum()
    if s <= 0:
        return h0, _C_from_heights(h0)
    h = h / s
    nfft = 65536
    while nfft < 2 * N:
        nfft <<= 1
    _, conv = _conv_and_grad(h, N, nfft)
    K = min(K, conv.size)
    idx_top = np.argpartition(conv, -K)[-K:]

    def apply_A(x):
        _, c = _conv_and_grad(x, N, nfft)
        return c[idx_top]

    x_ref = h.copy()

    def apply_AT(y):
        g = np.zeros(N)
        for j, kk in enumerate(idx_top):
            if y[j] == 0.0:
                continue
            lo = max(0, kk - (N - 1))
            hi = min(N - 1, kk)
            idx = np.arange(lo, hi + 1)
            g[idx] += y[j] * x_ref[kk - idx]
        return g

    v = np.random.RandomState(0).randn(N)
    v = v / (np.linalg.norm(v) + 1e-30)
    L = 1.0
    for _ in range(power_iters):
        if time.process_time() - t0 > budget * time_frac:
            break
        Av = apply_A(v)
        w = apply_AT(Av)
        nw = np.linalg.norm(w)
        if nw < 1e-30:
            break
        v = w / nw
        L = nw
    L = max(L, 1e-12)
    step = 1.0 / (2.0 * L)

    best_h = h.copy()
    best_C = _C_from_heights(h)

    for it in range(steps):
        if time.process_time() - t0 > budget * time_frac:
            break
        x_ref = h
        _, conv = _conv_and_grad(h, N, nfft)
        g = np.zeros(N)
        for kk in idx_top:
            lo = max(0, kk - (N - 1))
            hi = min(N - 1, kk)
            idx = np.arange(lo, hi + 1)
            g[idx] += h[kk - idx]
        g /= float(K)
        h = h - step * g
        h = np.maximum(h, 0.0)
        ss = h.sum()
        if ss <= 0:
            h = np.ones(N) / N
        else:
            h = h / ss
        if (it & 15) == 15:
            C = _C_from_heights(h)
            if C < best_C:
                best_C = C
                best_h = h.copy()

    C = _C_from_heights(h)
    if C < best_C:
        best_C = C
        best_h = h.copy()
    return best_h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    best_h = None
    best_C = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_C = _C_from_heights(s)

    if best_h is None:
        best_h = np.ones(3000)
        best_C = _C_from_heights(best_h)

    time_frac = 0.92

    for cycle in range(2):
        if time.process_time() - t0 > budget_seconds * time_frac:
            break
        for k in [200, 50, 10, 3]:
            if time.process_time() - t0 > budget_seconds * time_frac:
                break
            try:
                h_new, C_new = _lbfgs_topk_weighted(
                    best_h, t0, budget_seconds, k=k, m=30,
                    maxiter=250, maxfun=500, time_frac=time_frac)
                if C_new < best_C:
                    best_C, best_h = C_new, h_new.copy()
            except Exception:
                pass
            if time.process_time() - t0 > budget_seconds * time_frac:
                break
            try:
                ha, Ca = _lbfgs_h_active(best_h, t0, budget_seconds,
                                         rel_tol=1e-9, m=30,
                                         maxiter=300, maxfun=600,
                                         time_frac=time_frac)
                if Ca < best_C:
                    best_C, best_h = Ca, ha
            except Exception:
                pass
            if time.process_time() - t0 > budget_seconds * time_frac:
                break
            try:
                hf, Cf = _lbfgs_h_exact(best_h, t0, budget_seconds,
                                        maxiter=300, maxfun=600, m=30,
                                        time_frac=time_frac)
                if Cf < best_C:
                    best_C, best_h = Cf, hf
            except Exception:
                pass

    # Multi-stage QP polishing: larger lag sets first, then smaller
    for (Kq, stepsq, pwr) in [(300, 800, 60), (100, 600, 40), (30, 400, 20)]:
        if time.process_time() - t0 >= budget_seconds * time_frac:
            break
        try:
            hq, Cq = _qp_polish(best_h, t0, budget_seconds, K=Kq,
                                steps=stepsq, time_frac=time_frac,
                                power_iters=pwr)
            if Cq < best_C:
                best_C, best_h = Cq, hq.copy()
        except Exception:
            pass
        if time.process_time() - t0 < budget_seconds * time_frac:
            try:
                hf, Cf = _lbfgs_h_exact(best_h, t0, budget_seconds,
                                        maxiter=300, maxfun=600, m=30,
                                        time_frac=time_frac)
                if Cf < best_C:
                    best_C, best_h = Cf, hf
            except Exception:
                pass

    # Final refinement with active + exact
    if time.process_time() - t0 < budget_seconds * time_frac:
        try:
            ha, Ca = _lbfgs_h_active(best_h, t0, budget_seconds,
                                     rel_tol=1e-9, m=30,
                                     maxiter=300, maxfun=600,
                                     time_frac=time_frac)
            if Ca < best_C:
                best_C, best_h = Ca, ha
        except Exception:
            pass
    if time.process_time() - t0 < budget_seconds * time_frac:
        try:
            hf, Cf = _lbfgs_h_exact(best_h, t0, budget_seconds,
                                    maxiter=300, maxfun=600, m=30,
                                    time_frac=time_frac)
            if Cf < best_C:
                best_C, best_h = Cf, hf
        except Exception:
            pass

    return np.asarray(best_h, dtype=float)

