    if time.process_time() - t0 < budget_seconds * time_frac:
        try:
            hf, Cf = _lbfgs_h_exact(best_h, t0, budget_seconds,
                                    maxiter=300, maxfun=600, m=30,
                                    time_frac=time_frac)
            if Cf < best_C:
                best_C, best_h = Cf, hf
        except Exception:
            pass

    # NEW EXPERIMENT: coarse N=5000 QP polish + exact L-BFGS, then upsample
    # and run full-N QP (K=100) plus exact polish.
    if time.process_time() - t0 < budget_seconds * time_frac * 0.80:
        try:
            hc5 = _block_average(best_h, 5000)
            Cc5 = _C_from_heights(hc5)
