            # Exact L-BFGS at N=5000.
            hf5, Cf5 = _lbfgs_h_exact(hc5, t0, budget_seconds,
                                      maxiter=300, maxfun=600, m=30,
                                      time_frac=time_frac * 0.88)
            if Cf5 < Cc5:
                Cc5, hc5 = Cf5, hf5.copy()
            # Upsample to full N.
            hu5 = _upsample(hc5, len(best_h))
            Cu5 = _C_from_heights(hu5)
            if Cu5 < best_C:
                best_C, best_h = Cu5, hu5
        except Exception:
            pass

    # Full-N QP with K=100/30 plus exact polish on the (possibly improved) h.
    if time.process_time() - t0 < budget_seconds * time_frac:
        try:
            hq, Cq = _qp_polish(best_h, t0, budget_seconds, K=100, steps=600,
                                time_frac=time_frac, power_iters=30)
            if Cq < best_C:
                best_C, best_h = Cq, hq
        except Exception:
            pass
    if time.process_time() - t0 < budget_seconds * time_frac:
        try:
