import time
from scipy.optimize import minimize


def _C_from_heights(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _conv_and_grad(h, N, nfft):
    S = h.sum()
    conv = np.fft.irfft(np.fft.rfft(h, nfft) ** 2, nfft)[:2 * N - 1]
    return S, conv


def _lbfgs_h_exact(h0, t0, budget, maxiter=600, maxfun=1200, m=30,
                   time_frac=0.90):
    h0 = np.maximum(np.asarray(h0, dtype=float), 1e-12)
    N = len(h0)
    nfft = 65536
    while nfft < 2 * N:
        nfft <<= 1
    state = {'best_h': h0.copy(), 'best_C': _C_from_heights(h0),
             'stop': False}

    def fun(h):
        if time.process_time() - t0 > budget * time_frac:
            state['stop'] = True
        h = np.maximum(h, 1e-12)
        S, conv = _conv_and_grad(h, N, nfft)
        k = int(np.argmax(conv))
        C = 2.0 * N * conv[k] / (S * S)
        g = np.zeros(N)
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        g[idx] = 4.0 * N * h[k - idx] / (S * S)
        g -= 2.0 * C / S
        if C < state['best_C']:
            state['best_C'] = C
            state['best_h'] = h.copy()
        return C, g

    try:
        minimize(fun, h0, jac=True, method='L-BFGS-B',
                 bounds=[(0.0, 1e6)] * N,
                 options={'maxiter': maxiter, 'maxfun': maxfun,
                          'ftol': 1e-18, 'gtol': 1e-12, 'm': m},
                 callback=lambda hk: (_ for _ in ()).throw(StopIteration)
                 if state['stop'] else None)
    except StopIteration:
        pass
    except Exception:
        pass

    return state['best_h'], state['best_C']


def _lbfgs_pnorm(h0, t0, budget, p=50, m=30, maxiter=300, maxfun=600,
                 time_frac=0.90):
    """Objective 2N*R/S^2 with R = p-norm of conv (smooth near-max)."""
    h0 = np.maximum(np.asarray(h0, dtype=float), 1e-12)
    N = len(h0)
    nfft = 65536
    while nfft < 2 * N:
        nfft <<= 1
    state = {'best_h': h0.copy(), 'best_C': _C_from_heights(h0),
             'stop': False}

    def fun(h):
        if time.process_time() - t0 > budget * time_frac:
            state['stop'] = True
        h = np.maximum(h, 1e-12)
        S, conv = _conv_and_grad(h, N, nfft)
        cmax = float(np.max(conv))
        if cmax <= 0:
            cmax = 1e-30
        r = conv / cmax
        rp = np.maximum(r, 0.0) ** p
        sp = float(np.sum(rp))
        if sp <= 0:
            sp = 1e-300
        R = cmax * sp ** (1.0 / p)
        C = 2.0 * N * R / (S * S)
        # weights w_k = (conv_k/cmax)^(p-1) / sum
        w = np.maximum(r, 0.0) ** (p - 1)
        sw = float(np.sum(w))
        if sw <= 0:
            sw = 1e-300
        w = w / sw
        g = np.zeros(N)
        for kk, wk in zip(np.nonzero(w)[0], w[np.nonzero(w)[0]]):
            lo = max(0, kk - (N - 1))
            hi = min(N - 1, kk)
            idx = np.arange(lo, hi + 1)
            g[idx] += wk * 4.0 * N * h[kk - idx] / (S * S)
        g -= 2.0 * C / S
        Cexact = 2.0 * N * cmax / (S * S)
        if Cexact < state['best_C']:
            state['best_C'] = Cexact
            state['best_h'] = h.copy()
        return C, g

    try:
        minimize(fun, h0, jac=True, method='L-BFGS-B',
                 bounds=[(0.0, 1e6)] * N,
                 options={'maxiter': maxiter, 'maxfun': maxfun,
                          'ftol': 1e-18, 'gtol': 1e-12, 'm': m},
                 callback=lambda hk: (_ for _ in ()).throw(StopIteration)
                 if state['stop'] else None)
    except StopIteration:
        pass
    except Exception:
        pass

    return state['best_h'], state['best_C']


def construct(budget_seconds, start):
    t0 = time.process_time()
    best_h = None
    best_C = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_C = _C_from_heights(s)

    if best_h is None:
