        best_C = _C_from_heights(best_h)

    time_frac = 0.90

    # --- Experiment: p-norm smoothing at p=20,50,100 then exact polish ---
    for p in (20, 50, 100):
        if time.process_time() - t0 < budget_seconds * time_frac:
            try:
                hp, Cp = _lbfgs_pnorm(best_h, t0, budget_seconds, p=p,
