def _block_average(h, Nc):
    h = np.asarray(h, dtype=float)
    N = len(h)
    if N == Nc:
        return h.copy()
    edges = np.linspace(0, N, Nc + 1)
    out = np.empty(Nc)
    for i in range(Nc):
        a = int(round(edges[i]))
        b = int(round(edges[i + 1]))
        if b <= a:
            b = a + 1
        out[i] = h[a:b].mean()
    return out


def _upsample(h, N):
    h = np.asarray(h, dtype=float)
    Nc = len(h)
    if Nc == N:
        return h.copy()
    x_old = (np.arange(Nc) + 0.5) / Nc
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _coarse_polish(h, t0, budget, time_frac):
    """Run stdpen(100) -> stdpen(30) -> exact at coarse N, return best."""
    best_h = np.maximum(np.asarray(h, dtype=float), 1e-12)
    best_C = _C_from_heights(best_h)

    if time.process_time() - t0 < budget * time_frac:
        try:
            hv, Cv = _lbfgs_topk_stdpen_h(best_h, t0, budget, k=100,
                                          lam=1e-2, m=30, maxiter=300,
                                          maxfun=600, time_frac=time_frac)
            if Cv < best_C:
                best_C, best_h = Cv, hv.copy()
        except Exception:
            pass

    if time.process_time() - t0 < budget * time_frac:
        try:
            hv, Cv = _lbfgs_topk_stdpen_h(best_h, t0, budget, k=30,
                                          lam=3e-2, m=30, maxiter=400,
                                          maxfun=800, time_frac=time_frac)
            if Cv < best_C:
                best_C, best_h = Cv, hv.copy()
        except Exception:
            pass

    if time.process_time() - t0 < budget * time_frac:
        try:
            hf, Cf = _lbfgs_h_exact(best_h, t0, budget, maxiter=300,
                                    maxfun=600, m=30, time_frac=time_frac)
            if Cf < best_C:
                best_C, best_h = Cf, hf
        except Exception:
            pass

    return best_h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    best_h = None
    best_C = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_C = _C_from_heights(s)

    if best_h is None:
        best_h = np.ones(3000)
        best_C = _C_from_heights(best_h)

    time_frac = 0.85
    Nc = 3000

    # --- Coarse stage: block-average start, perturb, polish, keep best ---
    h_coarse = _block_average(best_h, Nc)
    x = (np.arange(Nc) + 0.5) / Nc

    eps_list = [0.005, 0.01, 0.02]
    m_list = [1, 2, 3, 4]
    rng = np.random.RandomState(12345)

    trials = []
    for eps in eps_list:
        for m in m_list:
            phi = rng.uniform(0, 2 * np.pi)
            trials.append((eps, m, phi))

    best_coarse_h = h_coarse.copy()
    best_coarse_C = _C_from_heights(h_coarse)

    # Reserve time: coarse trials get ~60% of budget, full chain the rest.
    coarse_deadline = t0 + budget_seconds * 0.60

    for (eps, m, phi) in trials:
        if time.process_time() > coarse_deadline:
            break
        try:
            pert = np.exp(eps * np.sin(2 * np.pi * m * x + phi))
            h_try = np.maximum(h_coarse * pert, 1e-12)
            h_pol, C_pol = _coarse_polish(h_try, t0, coarse_deadline,
                                          time_frac=0.98)
            if C_pol < best_coarse_C:
