    h_full = _upsample(best_coarse_h, N_full)

    # Compare with original start upsampled, keep better as seed
    if best_h is not None and len(best_h) == N_full:
        if _C_from_heights(best_h) <= _C_from_heights(h_full):
            h_full = best_h.copy()

    if _C_from_heights(h_full) < best_C:
        best_C = _C_from_heights(h_full)
        best_h = h_full.copy()

    # p0173's full chain
    if time.process_time() - t0 < budget_seconds * time_frac:
        try:
            hv, Cv = _lbfgs_topk_stdpen_h(best_h, t0, budget_seconds, k=100,
                                          lam=1e-2, m=30, maxiter=300,
                                          maxfun=600, time_frac=time_frac)
            if Cv < best_C:
                best_C, best_h = Cv, hv.copy()
        except Exception:
            pass

    if time.process_time() - t0 < budget_seconds * time_frac:
        try:
            hf, Cf = _lbfgs_h_exact(best_h, t0, budget_seconds,
                                    maxiter=500, maxfun=1000, m=30,
                                    time_frac=time_frac)
            if Cf < best_C:
                best_C, best_h = Cf, hf
        except Exception:
            pass

    if time.process_time() - t0 < budget_seconds * time_frac:
        try:
            hv, Cv = _lbfgs_topk_stdpen_h(best_h, t0, budget_seconds, k=30,
                                          lam=3e-2, m=30, maxiter=400,
                                          maxfun=800, time_frac=time_frac)
            if Cv < best_C:
                best_C, best_h = Cv, hv.copy()
        except Exception:
            pass

    if time.process_time() - t0 < budget_seconds * time_frac:
        try:
