    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C_from_heights(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _conv_and_grad(h, N, nfft):
    S = h.sum()
    conv = np.fft.irfft(np.fft.rfft(h, nfft) ** 2, nfft)[:2 * N - 1]
    return S, conv


def _lbfgs_h_exact(h0, t0, budget, maxiter=600, maxfun=1200, m=30,
                   time_frac=0.90):
    h0 = np.maximum(np.asarray(h0, dtype=float), 1e-12)
    N = len(h0)
    nfft = 65536
    while nfft < 2 * N:
        nfft <<= 1
    state = {'best_h': h0.copy(), 'best_C': _C_from_heights(h0),
             'stop': False}

    def fun(h):
        if time.process_time() - t0 > budget * time_frac:
            state['stop'] = True
        h = np.maximum(h, 1e-12)
        S, conv = _conv_and_grad(h, N, nfft)
        k = int(np.argmax(conv))
        C = 2.0 * N * conv[k] / (S * S)
        g = np.zeros(N)
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        g[idx] = 4.0 * N * h[k - idx] / (S * S)
        g -= 2.0 * C / S
        if C < state['best_C']:
            state['best_C'] = C
            state['best_h'] = h.copy()
        return C, g

    try:
        minimize(fun, h0, jac=True, method='L-BFGS-B',
                 bounds=[(0.0, 1e6)] * N,
                 options={'maxiter': maxiter, 'maxfun': maxfun,
                          'ftol': 1e-18, 'gtol': 1e-12, 'm': m},
                 callback=lambda hk: (_ for _ in ()).throw(StopIteration)
                 if state['stop'] else None)
    except StopIteration:
        pass
    except Exception:
        pass

    return state['best_h'], state['best_C']


def _trust_constr_log_exact(h0, t0, budget, nfft=8192, maxiter=300,
                            time_frac=0.85):
    """trust-constr on exact C(z), z=log(h)."""
    h0 = np.maximum(np.asarray(h0, dtype=float), 1e-12)
    N = len(h0)
    while nfft < 2 * N:
        nfft <<= 1
    z0 = np.log(h0)
    state = {'best_h': h0.copy(), 'best_C': _C_from_heights(h0),
             'stop': False}

    def fun(z):
        if time.process_time() - t0 > budget * time_frac:
            state['stop'] = True
        z = np.clip(z, -30.0, 30.0)
        h = np.exp(z)
        S, conv = _conv_and_grad(h, N, nfft)
        k = int(np.argmax(conv))
        C = 2.0 * N * conv[k] / (S * S)
        g = np.zeros(N)
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        g[idx] = 4.0 * N * h[k - idx] / (S * S)
        g -= 2.0 * C / S
        gz = g * h
        if C < state['best_C']:
            state['best_C'] = C
            state['best_h'] = h.copy()
        return C, gz

    try:
        minimize(fun, z0, jac=True, method='trust-constr',
                 bounds=[(-30.0, 30.0)] * N,
                 options={'maxiter': maxiter, 'gtol': 1e-12,
                          'xtol': 1e-14, 'barrier_tol': 1e-12,
                          'verbose': 0},
                 callback=lambda zk, st: (_ for _ in ()).throw(StopIteration)
                 if state['stop'] else None)
    except StopIteration:
        pass
    except Exception:
        pass

    return state['best_h'], state['best_C']


def _lbfgs_topk_stdpen_h(h0, t0, budget, k=100, lam=1e-2, m=30,
                         maxiter=300, maxfun=600, time_frac=0.85):
    h0 = np.maximum(np.asarray(h0, dtype=float), 1e-12)
    N = len(h0)
    nfft = 65536
    while nfft < 2 * N:
        nfft <<= 1
    state = {'best_h': h0.copy(), 'best_C': _C_from_heights(h0),
             'stop': False}

    def fun(h):
        if time.process_time() - t0 > budget * time_frac:
            state['stop'] = True
        h = np.maximum(h, 1e-12)
        S, conv = _conv_and_grad(h, N, nfft)
        kk = min(k, conv.size)
        idx_top = np.argpartition(conv, -kk)[-kk:]
        vals = conv[idx_top]
        mean_v = float(np.mean(vals))
        var_v = float(np.var(vals))
        if mean_v <= 0:
            mean_v = 1e-30
        std_v = np.sqrt(max(var_v, 0.0))
        Ck = 2.0 * N * mean_v / (S * S)
        pen = lam * std_v / mean_v
        obj = Ck + pen

        g = np.zeros(N)
        for kpos in idx_top:
            lo = max(0, kpos - (N - 1))
            hi = min(N - 1, kpos)
            idx = np.arange(lo, hi + 1)
            g[idx] += (1.0 / kk) * 4.0 * N * h[kpos - idx] / (S * S)
        g -= 2.0 * Ck / S

        inv_m = 1.0 / mean_v
        inv_m2 = inv_m * inv_m
        if std_v > 1e-30:
            inv_s = 1.0 / std_v
        else:
            inv_s = 0.0
        dpen_dv = lam * ((2.0 / kk) * (vals - mean_v) * inv_s * inv_m
                         - std_v * inv_m2 / kk)
        for j, kpos in enumerate(idx_top):
            coef = dpen_dv[j]
            if coef == 0.0:
                continue
            lo = max(0, kpos - (N - 1))
            hi = min(N - 1, kpos)
            idx = np.arange(lo, hi + 1)
            g[idx] += coef * h[kpos - idx]

        Cexact = 2.0 * N * conv.max() / (S * S)
        if Cexact < state['best_C']:
            state['best_C'] = Cexact
            state['best_h'] = h.copy()
        return obj, g

    try:
        minimize(fun, h0, jac=True, method='L-BFGS-B',
                 bounds=[(0.0, 1e6)] * N,
                 options={'maxiter': maxiter, 'maxfun': maxfun,
                          'ftol': 1e-18, 'gtol': 1e-12, 'm': m},
                 callback=lambda hk: (_ for _ in ()).throw(StopIteration)
                 if state['stop'] else None)
    except StopIteration:
        pass
    except Exception:
        pass

    return state['best_h'], state['best_C']


def _block_average(h, Nout):
    h = np.asarray(h, dtype=float)
    N = len(h)
    if N == Nout:
        return h.copy()
    edges = np.linspace(0, N, Nout + 1)
    out = np.empty(Nout)
    for i in range(Nout):
        a = int(round(edges[i]))
        b = int(round(edges[i + 1]))
        if b <= a:
            b = min(N, a + 1)
        out[i] = h[a:b].mean()
    return out


def _upsample(h, Nout):
    h = np.asarray(h, dtype=float)
    N = len(h)
    if N == Nout:
        return h.copy()
    x_old = (np.arange(N) + 0.5) / N
    x_new = (np.arange(Nout) + 0.5) / Nout
    return np.interp(x_new, x_old, h)


